play:grid;grid-template-columns:minmax(100px,1fr) 70px 68px 68px 20px;gap:7px;align-items:center}.cart-cols{padding:9px 17px;background:#f4f8fb;color:#718297;font-size:10px;font-weight:800}.item{padding:10px 17px;border-bottom:1px solid #edf2f6}.item strong,.item em{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.item strong{font-size:11px}.item em{font-size:10px;color:var(--muted);font-style:normal}.qty{display:flex;border:1px solid #dce6ef;border-radius:4px}.qty button,.remove{border:0;background:transparent;color:#27679f;cursor:pointer}.qty input{width:25px;border:0;padding:3px;text-align:center}.line{font-size:11px;font-weight:700}.remove{color:#df5560;font-size:17px}.empty{min-height:155px;display:grid;place-content:center;gap:6px;text-align:center;color:#8493a2}.empty b{font-size:13px}.empty small{font-size:11px}details{border-top:1px solid var(--line)}summary{padding:11px 17px;color:#58718a;font-size:12px;font-weight:700;cursor:pointer}.options{padding:0 17px 12px;margin:0;grid-template-columns:1fr 1fr}.options input,.options select{height:34px;padding:6px}.totals{border-top:1px solid var(--line);padding:10px 17px}.totals div{display:flex;justify-content:space-between;padding:4px;color:#61758a;font-size:12px}.total{margin-top:4px;padding-top:9px!important;border-top:1px solid #dbe7f0;color:var(--blue)!important;font-size:17px!important}.total b{color:var(--blue)}footer{display:grid;grid-template-columns:.8fr 1.2fr;gap:8px;padding:13px 17px;background:#f7fafd}footer>*{border:0;border-radius:5px;min-height:40px;display:grid;place-items:center;font:700 12px Arial;cursor:pointer}footer a{border:1px solid #d5e1eb;background:#fff;color:#587088}footer button{background:linear-gradient(135deg,#1682df,#0864bd);color:#fff}.modal{position:fixed;inset:0;z-index:40;background:#15253677;display:grid;place-items:center}.modal>div{position:relative;width:min(440px,92vw);max-height:80vh;overflow:auto;background:#fff;border-radius:9px;padding:22px}.mod