<script>
const products=@json($productOptions),services=@json($serviceOptions),old=@json(old('items',[]));let n=0,edited=false;const $=x=>document.querySelector(x),money=x=>'$'+Math.round(x||0).toLocaleString('es-CO'),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function draw(q=''){let a=products.filter(p=>(p.name+' '+(p.barcode||p.sku||p.code)).toLowerCase().includes(q.toLowerCase()));$('#products').innerHTML=a.map(p=>`<button class="product" type="button" data-id="${p.id}">${p.image_url?`<img class="pic" src="${esc(p.image_url)}">`:'<span class="pic">⚙</span>'}<span><span class="name">${esc(p.name)}</span><span class="code">${esc(p.barcode||p.sku||p.code)} · Stock: ${p.stock}</span></span><span class="price">${money(p.price)}</span></button>`).join('');$('#counter').textContent=`${a.length} productos en inventario`;$('#noProducts').hidden=!!a.length;document.querySelectorAll('.product').forEach(b=>b.onclick=()=>add('product',b.dataset.id));}
function add(type,id,qty=1,price=null){let a=(type==='product'?products:services).find(x=>x.id==id),row=[...document.querySelectorAll('.item')].find(x=>x.dataset.type===type&&x.dataset.id==id);if(row){let i=row.querySelector('[data-qty]');i.value=+i.value+qty}else{let p=price??a.price;row=document.createElement('div');row.className='item';row.dataset.type=type;row.dataset.id=id;row.dataset.price=p;row.dataset.tax=a.tax_rate||0;row.innerHTML=`<input type="hidden" name="items[${n}][item_type]" value="${type}"><input type="hidden" name="items[${n}][${type}_id]" value="${id}"><input type="hidden" name="items[${n}][unit_price]" value="${p}"><div><strong>${esc(a.name)}</strong><em>${type==='service'?'Servicio':esc(a.barcode||a.sku||a.code)}</em></div><div class="qty"><button type="button">−</button><input data-qty name="items[${n}][quantity]" type="number" min="1" value="${qty}"><button type="button">+</button></div><span class="unit line">${money(p)}</span><span class="line totalLine"></span><button class="remove" type="button">×</button>`;$('#items').append(row);n++;row.querySelectorAll('.qty button').forEach((b,i)=>b.onclick=()=>{let x=row.querySelector('[data-qty]');x.value=Math.max(1,+x.value+(i?1:-1));calc()});row.querySelector('[data-qty]').oninput=calc;row.querySelector('.remove').onclick=()=>{row.remove();calc()}}calc()}
function calc(){let sub=0,tax=0,count=0;document.querySelectorAll('.item').forEach(r=>{let q=+r.querySelector('[data-qty]').value||0,l=q*(+r.dataset.price);sub+=l;tax+=l*(+r.dataset.tax/100);count+=q;r.querySelector('.totalLine').textContent=money(l)});let d=+$('#discount').value||0,t=Math.max(sub-d,0)+tax,credit=$('#payment').value==='credito';if(!edited)$('#paid').value=credit?0:t.toFixed(2);$('#subtotal').textContent=money(sub);$('#tax').textContent=money(tax);$('#discountValue').textContent='-'+money(d);$('#total').textContent=money(t);$('#changeLabel').textContent=credit?'Saldo':'Cambio';$('#change').textContent=money(credit?Math.max(t-(+$('#paid').value||0),0):Math.max((+$('#paid').value||0)-t,0));$('#empty').hidden=!!count;$('#cartTitle').textContent=count?`${count} producto${count===1?'':'s'} en la venta`:'Tu carrito está vacío'}
$('#search').oninput=e=>draw(e.target.value);$('#search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();let v=e.target.value.trim(),p=products.find(x=>[x.barcode,x.sku,x.code].includes(v));if(p){add('product',p.id);e.target.value='';draw()}else $('#message').textContent='Producto no encontrado.'}};$('#discount').oninput=calc;$('#paid').oninput=()=>{edited=true;calc()};$('#payment').onchange=()=>{edited=false;calc()};$('#invoice').onchange=()=>{$('#customer').required=$('#invoice').value==='electronica'};$('#services').onclick=()=>$('#modal').hidden=false;$('#close').onclick=()=>$('#modal').hidden=true;document.addEventListener('keydown',event=>{if(event.key==='Escape')$('#modal').hidden=true});$('#serviceList').innerHTML=services.map(s=>`<button class="service" type="button" data-id="${s.id}"><strong>${esc(s.name)}</strong><span>${money(s.price)}</span></button>`).join('')||'No hay servicios activos.';document.querySelectorAll('.service').forEach(b=>b.onclick=()=>{add('service',b.dataset.id);$('#modal').hidden=true});$('#saleForm').onsubmit=e=>{if(!document.querySelector('.item')){e.preventDefault();$('#message').textContent='Agrega al menos un producto o servicio.'}};old.forEach(x=>add(x.item_type,x.item_type==='service'?x.service_id:x.product_id,x.quantity||1,x.unit_price));draw();calc();
</script>
<script>
const togglePaymentExtras=()=>{const method=$('#payment').value,credit=method==='credito';$('#due').hidden=!credit;$('#creditMethod').hidden=!credit;$('#dueDate').required=credit;$('#mixed').hidden=method!=='mixto'};
let paymentLine=0;$('#addPayment').onclick=()=>{let i=paymentLine++,r=document.createElement('div');r.className='payment-line';r.innerHTML=`<select name="payments[${i}][payment_method]"><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option><option value="otro">Otro</option></select><input name="payments[${i}][amount]" type="number" min=".01" step=".01" required><button type="button">×</button>`;r.querySelector('button').onclick=()=>r.remove();$('#paymentLines').append(r)};
$('#payment').addEventListener('change',togglePaymentExtras);togglePaymentExtras();
@foreach(old('payments',[]) as $payment) $('#addPayment').click(); $('#paymentLines').lastElementChild.querySelector('select').value=@json($payment['payment_method'] ?? 'efectivo'); $('#paymentLines').lastElementChild.querySelector('input').value=@json($payment['amount'] ?? ''); @endforeach
</script>
